const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Client details from the calendar event: "Email: / Name: / Service: / Telegram:" lines in the description, else the first guest
const parseEvent = e => {
  const desc = String(e.description || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '');
  const pick = re => ((desc.match(re) || [])[1] || '').trim();
  const guest = (e.attendees || []).find(a => a.email && !a.self && !a.organizer && !a.resource) || {};
  const title = String(e.summary || 'Appointment');
  return { id: String(e.id), start: DateTime.fromISO(e.start?.dateTime || ''), end: DateTime.fromISO(e.end?.dateTime || ''),
    email: (pick(/(?:^|\n)\s*e-?mail\s*[:=]\s*([^\s<>]+@[^\s<>]+)/i) || guest.email || '').toLowerCase(),
    name: pick(/(?:^|\n)\s*(?:name|client)\s*[:=]\s*([^\n]+)/i) || guest.displayName || title.split(/\s[-–:|]\s/)[0].trim(),
    service: pick(/(?:^|\n)\s*service\s*[:=]\s*([^\n]+)/i) || title.split(/\s[-–:|]\s/).slice(1).join(' ').trim() || title,
    telegram: pick(/(?:^|\n)\s*telegram\s*[:=]\s*(-?\d+)/i), title, cancelled: e.status === 'cancelled' || /^CANCELLED/i.test(title) };
};

// Which appointments need a reminder now? The tightest reminder window that has opened, once each.
const S = $('Set reminder settings').first().json;
const tz = S.timezone || 'Europe/London';
const offsets = String(S.reminder_hours || '24,2').split(',').map(Number).filter(n => n > 0);
const log = {};
for (const r of $('Read reminder log').all().map(i => i.json)) if (r.appointment_id) log[String(r.appointment_id)] = r;
const now = DateTime.now();
const out = [];
for (const e of $('Get upcoming appointments').all().map(i => i.json)) {
  if (!e.id || !e.start?.dateTime) continue;
  const a = parseEvent(e);
  if (a.cancelled || !a.email || !a.start.isValid) continue;
  const left = a.start.diff(now, 'hours').hours;
  if (left <= 0) continue;
  const row = log[a.id] || {};
  const moved = row.start && DateTime.fromISO(String(row.start)).toMillis() !== a.start.toMillis();
  const sent = moved ? [] : String(row.reminders_sent || '').split(',').map(s => s.trim()).filter(Boolean);
  const due = offsets.filter(o => left <= o);
  if (!due.length) continue;
  const o = Math.min(...due);
  if (sent.includes(String(o))) continue;
  const when = a.start.setZone(tz).toFormat("cccc d LLLL 'at' HH:mm");
  const html = `<p>Hi ${esc(a.name.split(' ')[0] || 'there')},</p><p>A reminder of your <b>${esc(a.service)}</b> with ${esc(S.business_name)} on <b>${when}</b>${S.business_address ? ` at ${esc(S.business_address)}` : ''}.</p>
<p>Can't make it? Please reply to this e-mail${S.booking_page_url && !String(S.booking_page_url).includes('YOUR_') ? ` or <a href="${S.booking_page_url}">pick a new time</a>` : ''} so someone else can have the slot.</p><p>See you soon,<br>${esc(S.business_name)}</p>`;
  out.push({ json: { to: a.email, subject: `Reminder: your ${a.service} on ${when}`, html,
    row: { appointment_id: a.id, start: a.start.toISO(), client_name: a.name, client_email: a.email, service: a.service,
      reminders_sent: [...sent, String(o)].join(','), last_reminder: now.toFormat('yyyy-MM-dd HH:mm') } } });
}
return out;

