// Tomorrow's appointments for the owner, with anyone missing an e-mail address (they get no reminder)
const S = $('Set agenda settings').first().json;
const tz = S.timezone || 'Europe/London';
const list = $("Get tomorrow's appointments").all().map(i => i.json).filter(e => e.id && e.start?.dateTime).map(parseEvent).filter(a => !a.cancelled);
const day = DateTime.now().setZone(tz).plus({ days: 1 }).toFormat('cccc d LLLL');
const li = list.map(a => `<li><b>${a.start.setZone(tz).toFormat('HH:mm')}</b> ${esc(a.name)}: ${esc(a.service)}${a.email ? '' : ' <span style="color:#b42318">(no e-mail, no reminder)</span>'}</li>`).join('');
return [{ json: { subject: `Tomorrow (${day}): ${list.length} appointment(s)`, html: list.length ? `<ul>${li}</ul>` : '<p>Nothing booked for tomorrow.</p>' } }];
